package de.eldoria.bloodnight.generated;

import de.eldoria.bloodnight.api.CompiledBehaviour;
import de.eldoria.bloodnight.api.MobContext;
import de.eldoria.bloodnight.graph.runtime.BukkitRuntime;
import de.eldoria.bloodnight.graph.runtime.Registries;
import de.eldoria.graph.std.runtime.Cooldown;
import de.eldoria.graph.std.runtime.TimeUnit;
import io.papermc.paper.registry.RegistryKey;
import java.util.Objects;
import org.bukkit.Particle;
import org.bukkit.entity.Skeleton;
import org.bukkit.entity.Spider;
import org.bukkit.event.entity.EntityDamageEvent;
import org.bukkit.event.entity.EntityDeathEvent;
import org.bukkit.event.entity.EntityTargetLivingEntityEvent;
import org.bukkit.potion.PotionEffect;
import org.bukkit.potion.PotionEffectType;

public final class SpeedSkeletonRiderBehaviour implements CompiledBehaviour {
    private static final EntityDamageEvent.DamageCause SUFFOCATION = EntityDamageEvent.DamageCause.SUFFOCATION;

    private static final Particle CAMPFIRE_COSY_SMOKE = Registries.entry(RegistryKey.PARTICLE_TYPE, "minecraft:campfire_cosy_smoke");

    private static final TimeUnit MILLISECONDS = TimeUnit.MILLISECONDS;

    private static final PotionEffectType SPEED = Registries.entry(RegistryKey.MOB_EFFECT, "minecraft:speed");

    private final MobContext context;

    private Cooldown cooldown;

    public SpeedSkeletonRiderBehaviour(MobContext context) {
        this.context = context;
        // node #45 function.cooldown
        this.cooldown = new Cooldown();
    }

    @Override
    public void onExtensionDamage(EntityDamageEvent event) {
        // node #6 event.extension_damage
        // node #8 flow.branch
        if (!(Objects.equals(event.getCause(), SUFFOCATION))) return;
        // node #7 cancellable.mutate
        event.setCancelled(true);
        // node #9
    }

    @Override
    public void onExtensionDeath(EntityDeathEvent event) {
        // node #17 event.extension_death
        // node #20 flow.branch
        // node #18 mob.self
        final Spider self = ((Spider) this.context.entity());
        if (self.isDead()) return;
        // node #19 living_entity.damage
        self.damage(self.getHealth());
        // node #21
    }

    @Override
    public void onNightEnd() {
        // node #28 mob.night_end
        // node #30 world.spawn_particle
        // node #29 mob.self
        final Spider self = ((Spider) this.context.entity());
        BukkitRuntime.particles(this.context, self.getWorld(), CAMPFIRE_COSY_SMOKE, self.getEyeLocation(), 30, 1.5d, 1.0d, 1.5d, null);
        // node #31
    }

    @Override
    public void onTargetChange(EntityTargetLivingEntityEvent event) {
        // node #39 event.target_change
        // node #42 flow.branch
        // node #40 mob.extension
        final Skeleton extension = ((Skeleton) this.context.extension());
        if (extension == null) return;
        // node #41 mob.mutate
        extension.setTarget(event.getTarget());
        // node #43
    }

    @Override
    public void onTick() {
        // node #51 mob.tick
        // node #54 flow.branch
        // node #52 function.cooldown
        final boolean cooldown = this.cooldown.ready(MILLISECONDS.toMillis(30000.0d));
        if (!cooldown) return;
        // node #53 living_entity.apply_effect
        ((Spider) this.context.entity()).addPotionEffect(new PotionEffect(SPEED, (int) (60.0d * 20), 1, true, true));
        // node #55
    }
}
